-- supabase/sql/exam_question_bank_neet_ug_set2.sql
--
-- Second curated question-bank batch for 'NEET UG' (see exam_patterns_neet_ug.sql for the exam's
-- structure, and exam_question_bank_neet_ug_set1.sql for the first batch -- same table/schema, no
-- migration needed). All-new questions, no overlap with Set 1.
--
-- Same format as Set 1: every row is format='mcq' with a single isCorrect:true option, matching
-- NEET UG's 100% single-best-response format. 16 chapters (4 each across Physics, Chemistry,
-- Botany, Zoology) each get 4 questions.
--
-- Run this once in the Supabase SQL Editor, after exam_patterns_neet_ug.sql and
-- exam_question_bank_neet_ug_set1.sql.

insert into exam_question_bank (exam_name, subject, chapter, difficulty, format, text, options, numerical_answer, explanation) values

-- Physics: Mechanics
('NEET UG', 'Physics', 'Mechanics', 'easy', 'mcq',
 'The SI unit of momentum is:',
 '[{"text":"kg m/s","isCorrect":true},{"text":"kg m/s^2","isCorrect":false},{"text":"N/s","isCorrect":false},{"text":"kg m^2/s","isCorrect":false}]'::jsonb,
 null, 'Momentum is the product of mass and velocity, giving it the SI unit kg m/s.'),
('NEET UG', 'Physics', 'Mechanics', 'medium', 'mcq',
 'A ball thrown vertically upward (ignoring air resistance) returns to the thrower''s hand with the same speed it was thrown. This is an example of:',
 '[{"text":"Conservation of momentum only","isCorrect":false},{"text":"Conservation of mechanical energy","isCorrect":true},{"text":"Newton''s third law","isCorrect":false},{"text":"Conservation of angular momentum","isCorrect":false}]'::jsonb,
 null, 'In the absence of air resistance, gravitational potential energy converts back fully to kinetic energy on the way down, so total mechanical energy is conserved, and speed is restored.'),
('NEET UG', 'Physics', 'Mechanics', 'medium', 'mcq',
 'The moment of inertia of a rigid body about a given axis depends on:',
 '[{"text":"Its mass alone","isCorrect":false},{"text":"Its mass and how that mass is distributed relative to the axis","isCorrect":true},{"text":"Its velocity alone","isCorrect":false},{"text":"Its temperature","isCorrect":false}]'::jsonb,
 null, 'Moment of inertia depends on both the total mass of a body and how that mass is distributed relative to the rotation axis -- mass farther from the axis contributes more.'),
('NEET UG', 'Physics', 'Mechanics', 'easy', 'mcq',
 'Newton''s third law of motion states that:',
 '[{"text":"An object at rest stays at rest unless acted upon by a force","isCorrect":false},{"text":"For every action, there is an equal and opposite reaction","isCorrect":true},{"text":"Force equals mass times acceleration","isCorrect":false},{"text":"Energy can neither be created nor destroyed","isCorrect":false}]'::jsonb,
 null, 'Newton''s third law states that for every action force exerted by one body on another, there is an equal and opposite reaction force exerted by the second body on the first.'),

